import { Component } from '@angular/core';
import { NarudzbineService } from '../narudzbine.service';
import jwt_decode from 'jwt-decode';
import { Order } from '../models/orders';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { RecenzijaService } from '../recenzija.service';

@Component({
  selector: 'app-prethodne-kupovine',
  templateUrl: './prethodne-kupovine.component.html',
  styleUrls: ['./prethodne-kupovine.component.css']
})
export class PrethodneKupovineComponent {
  userId: string = '';
  narudzbinaId: string = '';

  narudzbine: Order[] = [];
  isReviewModalOpen: boolean = false;
  currentOrderId: string = '';
  currentProdavnicaId: string = '';
  reviewForm: FormGroup;
  ocena: number = 0;

  constructor(
    private ordersService: NarudzbineService,
    private recenzijeService: RecenzijaService,
    private fb: FormBuilder
  ) {
    this.reviewForm = this.fb.group({
      ocena: [5, [Validators.required, Validators.min(1), Validators.max(5)]],
      komentar: ['']
    });
  }

  ngOnInit(): void {
    const token = localStorage.getItem('token');
    if (token) {
      const decodedToken: any = jwt_decode(token);
      this.userId = decodedToken.id;
      this.fetchNarudzbine();
    }
  }

  fetchNarudzbine() {
    this.ordersService.dohvatiNarudzbineZaKorisnika(this.userId).subscribe(
      (response: Order[]) => {
        this.narudzbine = response;
      },
      (error: any) => {
        console.error('Greška pri dohvatanju narudžbina:', error);
      }
    );
  }

  // ⬇⬇⬇ bitna izmena – podržava string | string[]
  getArtikalImage(imagePath: string | string[] | undefined): string {
    if (!imagePath) {
      return 'assets/no-image.png';
    }

    const path =
      Array.isArray(imagePath) && imagePath.length > 0
        ? imagePath[0]
        : (imagePath as string);

    if (!path) {
      return 'assets/no-image.png';
    }

    return `http://localhost:4000/${path}`;
  }

  getStatusExplanation(status: string): string {
    switch (status) {
      case 'U obradi':
        return 'Narudžbina je primljena i u procesu obrade.';
      case 'Poslato':
        return 'Vaši artikli su poslati i uskoro će stići na adresu.';
      case 'Potvrđeno':
      case 'Potvrdjeno':
        return 'Narudžbina je potvrđena i dostavljena.';
      default:
        return '';
    }
  }

  confirmDelivery(orderId: string) {
    const narudzbina: Order | undefined = this.narudzbine.find(
      (n) => n._id === orderId
    );

    if (narudzbina) {
      this.currentProdavnicaId = narudzbina.prodavnica;
      this.narudzbinaId = narudzbina._id;
      narudzbina.status = 'Potvrdjeno';

      this.ordersService.postaviStatusNaPotvrdjeno(orderId).subscribe(
        () => {
          this.openReviewModal();
        },
        (error) => {
          console.error('Greška pri potvrdi prijema narudžbine:', error);
        }
      );
    }
  }

  openReviewModal() {
    this.isReviewModalOpen = true;
  }

  closeReviewModal() {
    this.isReviewModalOpen = false;
    this.ocena = 0;
    this.reviewForm.reset({
      ocena: 5,
      komentar: ''
    });
  }

  rate(stars: number) {
    this.ocena = stars;
  }

  submitReview() {
    if (this.reviewForm.valid) {
      const komentar = this.reviewForm.get('komentar')?.value;

      this.recenzijeService
        .dodajRecenziju(
          this.userId,
          this.currentProdavnicaId,
          this.ocena,
          komentar,
          this.narudzbinaId
        )
        .subscribe(
          () => {
            this.closeReviewModal();
            alert('Hvala na recenziji!');
          },
          (error) => {
            console.error('Greška pri slanju recenzije:', error);
          }
        );
    }
  }
}
<div class="purchase-history-container">
  <h2>Prethodne kupovine</h2>

  <!-- Prolazimo kroz svaku narudžbinu -->
  <div *ngFor="let narudzbina of narudzbine; let i = index" class="order-section">
    <h3 [ngClass]="{'green-status': narudzbina.status === 'Poslato', 'red-status': narudzbina.status === 'Potvrdjeno'}">
      Status: {{ narudzbina.status }}
    </h3>

    <!-- Prikaz dugmeta za potvrđivanje prijema -->
    <button *ngIf="narudzbina.status === 'Poslato'" (click)="confirmDelivery(narudzbina._id)">Potvrdi prijem</button>
    <!-- Prolazimo kroz artikle u narudžbini -->

    <div class="artikli-container">
      <div class="artikal-card" *ngFor="let artikal of narudzbina.artikli">
        <img [src]="getArtikalImage(artikal.slike)" alt="Artikal slika" class="artikal-image" />
        <div class="artikal-info">
          <h3>{{ artikal.tip }}</h3>
          <p>Veličina: {{ artikal.velicina }}</p>
          <p>Boja: {{ artikal.boja }}</p>
          <p>Cena: {{ artikal.cena }} din</p>
        </div>
      </div>
    </div>

    <!-- Prikaz ukupne cene -->
    <p>Ukupna cena: {{ narudzbina.ukupnaCena }} din</p>

  </div>
</div>

<div *ngIf="isReviewModalOpen" class="review-modal">
  <div class="modal-content">
    <h2>Ostavite recenziju</h2>
    <form [formGroup]="reviewForm" (ngSubmit)="submitReview()">
      <div class="stars">
        <i class="fa fa-star" (click)="rate(1)" [class.filled]="ocena >= 1"></i>
        <i class="fa fa-star" (click)="rate(2)" [class.filled]="ocena >= 2"></i>
        <i class="fa fa-star" (click)="rate(3)" [class.filled]="ocena >= 3"></i>
        <i class="fa fa-star" (click)="rate(4)" [class.filled]="ocena >= 4"></i>
        <i class="fa fa-star" (click)="rate(5)" [class.filled]="ocena >= 5"></i>
      </div>

      <label for="komentar">Komentar:</label>
      <textarea id="komentar" formControlName="komentar" placeholder="Ostavite komentar"></textarea>

      <div class="modal-buttons">
        <button type="submit" [disabled]="!reviewForm.valid">Pošalji recenziju</button>
        <button type="button" (click)="closeReviewModal()">Zatvori</button>
      </div>
    </form>
  </div>
</div>
